export enum ProbeEnum {
  A = 'a',
  B = 'b'
}

export interface ProbePeriod {
  kind: string;
  type: string;
  start: string;
  end: string;
}

export interface ProbeTotals {
  views: number;
  visitors: number;
}

export class ProbePeriodClass implements ProbePeriod {
  kind: string = '';
  type: string = '';
  start: string = '';
  end: string = '';

  constructor(kind: string, type: string, start: string, end: string) {
    this.kind = kind;
    this.type = type;
    this.start = start;
    this.end = end;
  }

  describe(): string {
    return this.kind + ':' + this.start;
  }
}

export function probeRecordLiteral(): Record<string, Object> {
  const r: Record<string, Object> = {};
  r['num'] = 1;
  r['str'] = 'x';
  r['bool'] = true;
  return r;
}

export function probeReadNumber(src: Record<string, Object>, key: string): number {
  const raw = src[key];
  if (raw === undefined || raw === null) {
    return 0;
  }
  return raw as number;
}

export function probeReadRecord(src: Record<string, Object>, key: string): Record<string, Object> {
  const raw = src[key];
  if (raw === undefined || raw === null) {
    return {};
  }
  return raw as Record<string, Object>;
}

export function probeReadArray(src: Record<string, Object>, key: string): Object[] {
  const raw = src[key];
  if (raw === undefined || raw === null) {
    return [];
  }
  return raw as Object[];
}

export function probeReadStringArray(src: Record<string, Object>, key: string): string[] {
  const raw = src[key];
  if (raw === undefined || raw === null) {
    return [];
  }
  return raw as string[];
}

export function probeObjectLiteralToInterface(): ProbePeriod {
  const p: ProbePeriod = { kind: 'rolling', type: 'last_30_days', start: 'a', end: 'b' };
  return p;
}

export function probeObjectLiteralArray(): ProbePeriod[] {
  const list: ProbePeriod[] = [];
  list.push({ kind: 'a', type: 'b', start: 'c', end: 'd' });
  const direct: ProbePeriod[] = [
    { kind: 'a', type: 'b', start: 'c', end: 'd' }
  ];
  return list.concat(direct);
}

export function probeCastObjectToInterface(src: Record<string, Object>): ProbePeriod {
  const raw = src['period'];
  if (raw === undefined || raw === null) {
    return { kind: '', type: '', start: '', end: '' };
  }
  return raw as ProbePeriod;
}

export function probeNestedRecord(): Record<string, Object> {
  const inner: Record<string, Object> = {};
  inner['views'] = 100;
  const outer: Record<string, Object> = {};
  outer['totals'] = inner;
  outer['points'] = [inner];
  return outer;
}

export function probeNumbers(): Record<string, number> {
  const n: Record<string, number> = {};
  n['views'] = 5;
  return n;
}

export function probeJsonParse(text: string): Record<string, Object> {
  return JSON.parse(text) as Record<string, Object>;
}

export function probeJsonStringify(rec: Record<string, Object>): string {
  return JSON.stringify(rec);
}

export function probeDate(): string {
  const d: Date = new Date();
  d.setFullYear(2026);
  d.setMonth(9);
  d.setDate(30);
  const y: number = d.getFullYear();
  const m: number = d.getMonth() + 1;
  const day: number = d.getDate();
  return y.toString() + '-' + m.toString() + '-' + day.toString();
}

export function probeDateFromString(day: string): number {
  const parts: string[] = day.split('-');
  return parseInt(parts[0]) + parseInt(parts[1]) + parseInt(parts[2]);
}

export async function probeAsync(): Promise<number> {
  const v: number = await Promise.resolve(7);
  return v;
}

export function probeEnum(): string {
  return ProbeEnum.A;
}

export function probeEnumInRecord(): Record<string, Object> {
  const r: Record<string, Object> = {};
  r['kind'] = ProbeEnum.B;
  return r;
}

export function probeSpread(src: Record<string, Object>): Record<string, Object> {
  const copy: Record<string, Object> = {};
  const keys: string[] = Object.keys(src);
  for (const k of keys) {
    copy[k] = src[k];
  }
  return copy;
}

export function probeIndexOf(): number {
  const items: string[] = ['a', 'b'];
  return items.indexOf('a');
}

export function probeNumberKeys(): string[] {
  const n: Record<string, number> = {};
  n['a'] = 1;
  return Object.keys(n);
}

export function probeMap(): number {
  const m: Map<string, number> = new Map<string, number>();
  m.set('a', 1);
  return m.size;
}

export function probeNullAssign(): Object | null {
  return null;
}

export class ProbeHolder {
  private values: Record<string, Object> = {};
  private listeners: Array<() => void> = [];

  put(key: string, value: Object): void {
    this.values[key] = value;
    this.notify();
  }

  read(key: string): Object | undefined {
    return this.values[key];
  }

  subscribe(fn: () => void): void {
    this.listeners.push(fn);
  }

  private notify(): void {
    const snapshot: Array<() => void> = this.listeners;
    for (const fn of snapshot) {
      fn();
    }
  }
}

export function probeTryCatch(): string {
  try {
    throw new Error('x');
  } catch (e) {
    return 'caught';
  }
}

export function probeDefaultParam(src: Record<string, Object>, fallback: string = 'd'): string {
  const raw = src['name'];
  if (raw === undefined || raw === null) {
    return fallback;
  }
  return raw as string;
}

export function probeTernary(src: Record<string, Object>): number {
  return src['a'] === undefined ? 0 : (src['a'] as number);
}

export function probeNumbersFromArray(src: Object[]): number[] {
  const out: number[] = [];
  for (const item of src) {
    out.push(item as number);
  }
  return out;
}

export function probeTotalsLiteral(): ProbeTotals {
  return { views: 1, visitors: 2 };
}

export function probeStringPad(day: number): string {
  const asText: string = day.toString();
  return asText.length === 1 ? '0' + asText : asText;
}

export function probeStaticCounter(): number {
  return ProbeCounter.value;
}

class ProbeCounter {
  static value: number = 0;
  static bump(): number {
    ProbeCounter.value += 1;
    return ProbeCounter.value;
  }
}

export function probeSortByNumber(values: number[]): number[] {
  values.sort((a: number, b: number) => a - b);
  return values;
}

