import { probeAsync, probeCastObjectToInterface, probeDate, probeDateFromString, probeDefaultParam, probeEnum, probeEnumInRecord, probeHolderUsage, probeIndexOf, probeJsonParse, probeJsonStringify, probeMap, probeNestedRecord, probeNullAssign, probeNumberKeys, probeNumbers, probeNumbersFromArray, probeObjectLiteralArray, probeObjectLiteralToInterface, probeReadArray, probeReadNumber, probeReadRecord, probeReadStringArray, probeRecordLiteral, probeSortByNumber, probeSpread, probeStaticCounter, probeStringPad, probeTotalsLiteral, probeTryCatch, ProbeHolder } from '../feature/Probe';

@Entry
@Component
struct Index {
  private owner: MountedNewStatsPageOwner = NewStatsPageRuntime.createOwner();
  @State summary: string = 'Loading';
  private holder: ProbeHolder = new ProbeHolder();

  aboutToAppear(): void {
    const holder: ProbeHolder = this.holder;
    holder.subscribe(() => {
      this.summary = probeHolderUsage();
    });
    holder.put('k', 'v');
    const probe: string[] = [
      JSON.stringify(probeRecordLiteral()),
      probeReadNumber({}, 'x').toString(),
      JSON.stringify(probeReadRecord({}, 'x')),
      probeReadArray({}, 'x').length.toString(),
      probeReadStringArray({}, 'x').length.toString(),
      JSON.stringify(probeObjectLiteralToInterface()),
      JSON.stringify(probeObjectLiteralArray()),
      JSON.stringify(probeCastObjectToInterface({})),
      JSON.stringify(probeNestedRecord()),
      JSON.stringify(probeNumbers()),
      probeJsonParse('{}') !== undefined ? 'ok' : 'no',
      probeJsonStringify({}),
      probeDate(),
      probeDateFromString('2026-10-30').toString(),
      probeIndexOf().toString(),
      probeNumberKeys().length.toString(),
      probeEnum(),
      JSON.stringify(probeEnumInRecord()),
      probeMap().toString(),
      probeNullAssign() === null ? 'null' : 'notnull',
      probeTryCatch(),
      probeDefaultParam({}),
      probeTernaryValue().toString(),
      JSON.stringify(probeNumbersFromArray([])),
      JSON.stringify(probeTotalsLiteral()),
      probeStringPad(7),
      probeStaticCounter().toString(),
      JSON.stringify(probeSortByNumber([])),
      holder.read('k') !== undefined ? 'read' : 'none'
    ];
    this.summary = probe.join('|');
    void probeAsync().then(() => {
      this.owner.waitUntilReady().then(() => {
        this.summary = JSON.stringify(this.owner.currentState());
      });
    });
  }

  build() {
    Column({ space: 16 }) {
      Text('WordPress New Stats').fontSize(28).fontWeight(FontWeight.Bold)
      Text(this.summary).fontSize(14)
    }.width('100%').height('100%').padding(24)
  }
}

function probeHolderUsage(): string {
  return 'holder';
}

function probeTernaryValue(): number {
  return 0;
}

