 * Paging must never carry the window past the present edge. A rolling window
 * is bounded by its end date, a calendar period by its start date so that the
 * period containing today is still reachable.
 */
function reachesPresentEdge(period: NewStatsPeriod, today: string): boolean {
  const kind: string = period.kind;
  if (kind === NewStatsPeriodKind.ROLLING || kind === NewStatsPeriodKind.CUSTOM) {
    return diffNewStatsDays(today, period.end) >= 0;
  }
  return diffNewStatsDays(today, period.start) >= 0;
}

export function canPageNewStatsForward(period: NewStatsPeriod, today: string): boolean {
  return !reachesPresentEdge(shiftNewStatsPeriod(period, 1), today);
}

export function canPageNewStatsBackward(period: NewStatsPeriod): boolean {
  return true;
}

export function pageNewStatsForward(period: NewStatsPeriod, today: string): NewStatsPeriod | undefined {
  if (!canPageNewStatsForward(period, today)) {
    return undefined;
  }
  return shiftNewStatsPeriod(period, 1);
}

export function pageNewStatsBackward(period: NewStatsPeriod): NewStatsPeriod {
  return shiftNewStatsPeriod(period, -1);
}

export function newStatsPeriodSpanDays(period: NewStatsPeriod): number {
  return diffNewStatsDays(period.start, period.end) + 1;
}

