  if (isHourlyNewStatsPeriod(period)) {
    return [NewStatsMetric.VIEWS];
  }
  return ALL_METRICS;
}

export function supportsNewStatsChartMetric(period: NewStatsPeriod, metric: string): boolean {
  return supportedNewStatsChartMetrics(period).indexOf(metric) >= 0;
}

