import { buildNewStatsScreenSnapshot, NewStatsScreenSnapshot } from '../feature/NewStatsScreen';
import { NewStatsStore } from '../feature/NewStatsStore';

/**
 * Leaf used when the screen runs on its own: it records the effects the screen
 * dispatches so they can be inspected without a host application.
 */
export class RecordingNewStatsLeaf {
  private recorded: string[] = [];

  async emit(effect: { name: string }): Promise<void> {
    this.recorded.push(effect.name);
  }

  recordedNames(): string[] {
    return this.recorded;
  }
}

/**
 * Owns the screen's lifetime. It mounts the store, forwards user intent to it,
 * and exposes the state the page renders.
 */
export class MountedNewStatsPageOwner implements NewStatsPageOwner {
  private store?: NewStatsStore;
  private ready: Promise<void> = Promise.resolve();
  private listeners: Array<() => void> = [];
  private readonly pageOwnerId: string;
  private readonly controllerOwnerId: string;

  constructor(generation: number) {
    this.pageOwnerId = 'newstats-page-owner-' + generation.toString();
    this.controllerOwnerId = 'newstats-controller-' + generation.toString();
  }

  mount(context: common.UIAbilityContext, input: NewStatsInput, initialize: boolean): Promise<void> {
    this.ready = NewStatsStore.create(context, input, initialize).then((created: NewStatsStore) => {
      this.store = created;
      created.subscribe(() => {
        const snapshot: Array<() => void> = this.listeners;
        for (const listener of snapshot) {
          listener();
        }
      });
    });
    return this.ready;
  }

  async waitUntilReady(): Promise<void> {
    await this.ready;
  }

  async invoke(name: string, event: Record<string, Object>): Promise<void> {
    await this.ready;
    if (this.store === undefined) {
      throw new Error('NewStats store is not mounted');
    }
    await this.store.invoke(name, event);
  }

  currentState(): Record<string, Object> {
    return this.store === undefined ? {} : this.store.currentState();
  }

  currentPersistence(): Record<string, Object> {
    return this.store === undefined ? {} : this.store.currentPersistence();
  }

  screenSnapshot(): NewStatsScreenSnapshot {
    if (this.store === undefined) {
      return buildNewStatsScreenSnapshot({});
    }
    return buildNewStatsScreenSnapshot(this.store.currentState());
  }

  subscribe(listener: () => void): void {
    this.listeners.push(listener);
  }

  ownerId(): string {
    return this.pageOwnerId;
  }

  controllerId(): string {
    return this.controllerOwnerId;
  }

  storeSource(): string {
    return 'Index.NewStatsPageOwner.controller.store';
  }

  featureAvailable(): boolean {
    return this.store !== undefined;
  }
}

