import { common } from '@kit.AbilityKit';
import {
  buildNewStatsScreenSnapshot,
  NewStatsChartBarView,
  NewStatsLocationRowView,
  NewStatsMetricChipView,
  NewStatsScreenSnapshot,
  NewStatsSummaryCellView
} from '../feature/NewStatsScreen';
import { MountedNewStatsPageOwner, NewStatsPageRuntime } from './NewStatsPageOwner';

const CHART_HEIGHT: number = 132;
const MIN_BAR_HEIGHT: number = 6;

@Entry
@Component
struct Index {
  private owner?: MountedNewStatsPageOwner = undefined;
  @State ready: boolean = false;
  @State revision: number = 0;

  aboutToAppear(): void {
    NewStatsPageRuntime.ensureConfigured(getContext(this) as common.UIAbilityContext);
    const owner: MountedNewStatsPageOwner = NewStatsPageRuntime.createOwner();
    this.owner = owner;
    owner.subscribe(() => {
      this.revision += 1;
    });
    owner.waitUntilReady().then(() => {
      this.ready = true;
      this.revision += 1;
    });
  }

  aboutToDisappear(): void {
    this.owner = undefined;
  }

  private snapshot(): NewStatsScreenSnapshot {
    return this.owner === undefined ? buildNewStatsScreenSnapshot({}) : this.owner.screenSnapshot();
  }

  private dispatch(name: string, event: Record<string, Object>): void {
    const owner: MountedNewStatsPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    owner.invoke(name, event);
  }

  private barHeight(bar: NewStatsChartBarView): number {
    if (bar.isUpcoming) {
      return MIN_BAR_HEIGHT;
    }
    const filled: number = bar.fill * CHART_HEIGHT;
    return filled > MIN_BAR_HEIGHT ? filled : MIN_BAR_HEIGHT;
  }

  private barColor(bar: NewStatsChartBarView): string {
    if (bar.isUpcoming) {
      return '#E3E5E8';
    }
    return bar.isSelected ? '#1D6FCF' : '#7BA7E0';
  }

  @Builder
  private periodHeader(snapshot: NewStatsScreenSnapshot) {
    Row() {
      Button('<')
        .enabled(snapshot.canPageBackward)
        .onClick(() => {
          this.dispatch('navigateBackward', {});
        })
      Column({ space: 2 }) {
        Text(snapshot.periodLabel).fontSize(16).fontWeight(FontWeight.Bold)
        Text(snapshot.rangeLabel).fontSize(12).fontColor('#6C7480')
      }.layoutWeight(1).alignItems(HorizontalAlign.Center)
      Button('>')
        .enabled(snapshot.canPageForward)
        .onClick(() => {
          this.dispatch('navigateForwardAfterRestore', {});
        })
    }.width('100%').padding({ left: 12, right: 12, top: 12, bottom: 8 })
  }

  @Builder
  private metricSelector(snapshot: NewStatsScreenSnapshot) {
    Scroll() {
      Row({ space: 8 }) {
        ForEach(snapshot.metricChips, (chip: NewStatsMetricChipView) => {
          Text(chip.metric)
            .fontSize(13)
            .fontColor(chip.isSelected ? '#FFFFFF' : '#1D2329')
            .backgroundColor(chip.isSelected ? '#1D6FCF' : '#EDF0F3')
            .borderRadius(14)
            .padding({ left: 12, right: 12, top: 6, bottom: 6 })
            .onClick(() => {
              const event: Record<string, Object> = {};
              event['metric'] = chip.metric;
              this.dispatch('selectMetric', event);
            })
        }, (chip: NewStatsMetricChipView) => chip.metric)
      }.padding({ left: 12, right: 12 })
    }.scrollable(ScrollDirection.Horizontal).width('100%').margin({ bottom: 8 })
  }

  @Builder
  private chart(snapshot: NewStatsScreenSnapshot) {
    Column({ space: 6 }) {
      Row() {
        Text(snapshot.metricLabel).fontSize(14).fontWeight(FontWeight.Medium)
        Blank()
        Text(snapshot.chartTotalLabel).fontSize(20).fontWeight(FontWeight.Bold)
      }.width('100%').padding({ left: 12, right: 12 })

      if (snapshot.showsUnavailable) {
        Column({ space: 10 }) {
          Text(snapshot.unavailableLabel).fontSize(13).fontColor('#6C7480')
          Text('Pick a period that covers more than one day to compare this metric')
            .fontSize(12).fontColor('#8C949C')
        }.width('100%').padding(16).alignItems(HorizontalAlign.Center)
      } else if (snapshot.showsLoading) {
        Column() {
          LoadingProgress().width(24).height(24)
        }.width('100%').height(CHART_HEIGHT).justifyContent(FlexAlign.Center)
      } else if (snapshot.showsError) {
        Column({ space: 10 }) {
          Text('This content could not be loaded').fontSize(13).fontColor('#6C7480')
          Button('Retry').onClick(() => {
            this.dispatch('retry', {});
          })
        }.width('100%').padding(16).alignItems(HorizontalAlign.Center)
      } else {
        Row({ space: 6 }) {
          ForEach(snapshot.chartBars, (bar: NewStatsChartBarView) => {
            Column({ space: 4 }) {
              Blank().layoutWeight(1)
              Row()
                .width(18)
                .height(this.barHeight(bar))
                .borderRadius(4)
                .backgroundColor(this.barColor(bar))
              Text(bar.label).fontSize(10).fontColor('#6C7480')
            }
            .layoutWeight(1)
            .height(CHART_HEIGHT + 20)
            .justifyContent(FlexAlign.End)
            .onClick(() => {
              if (!bar.isActionable) {
                return;
              }
              const event: Record<string, Object> = {};
              event['index'] = bar.index;
              this.dispatch('tapChartBucket', event);
            })
          }, (bar: NewStatsChartBarView) => bar.key)
        }.width('100%').height(CHART_HEIGHT + 20).padding({ left: 12, right: 12 })
      }

      if (snapshot.showsCached) {
        Text('Showing saved results while they are checked for updates')
          .fontSize(11).fontColor('#8C949C').padding({ left: 12, right: 12, top: 6 })
      }

      if (snapshot.canDrillDown) {
        Button('Go to ' + snapshot.selectedBucketLabel)
          .fontSize(12)
          .margin({ left: 12, top: 6, bottom: 6 })
          .onClick(() => {
            this.dispatch('drillIntoSelectedBucket', {});
          })
      }
    }.width('100%')
  }

  @Builder
  private summaryRow(snapshot: NewStatsScreenSnapshot) {
    Row({ space: 8 }) {
      ForEach(snapshot.summaryRow, (cell: NewStatsSummaryCellView) => {
        Column({ space: 2 }) {
          Text(cell.value.toString()).fontSize(15).fontWeight(FontWeight.Bold)
          Text(cell.metric).fontSize(11).fontColor('#6C7480')
        }.layoutWeight(1).alignItems(HorizontalAlign.Center)
      }, (cell: NewStatsSummaryCellView) => cell.metric)
    }.width('100%').padding(12).backgroundColor('#F6F7F8').borderRadius(8)
  }

  @Builder
  private locationCard(snapshot: NewStatsScreenSnapshot) {
    Column({ space: 8 }) {
      Row({ space: 8 }) {
        Text('Countries').fontSize(13).fontColor('#1D2329')
          .onClick(() => {
            const event: Record<string, Object> = {};
            event['locationType'] = 'countries';
            this.dispatch('selectLocationType', event);
          })
        Text('Regions').fontSize(13).fontColor('#1D2329')
          .onClick(() => {
            const event: Record<string, Object> = {};
            event['locationType'] = 'regions';
            this.dispatch('selectLocationType', event);
          })
        Blank()
      }.width('100%')

      if (snapshot.showsPlanGate) {
        Column({ space: 8 }) {
          Text('Region data needs a plan that includes it').fontSize(12).fontColor('#6C7480')
          Button(snapshot.planActionLabel).fontSize(12).onClick(() => {
            this.dispatch('openPlanAction', {});
          })
        }.width('100%').alignItems(HorizontalAlign.Start)
      } else if (snapshot.showsAuthError) {
        Column({ space: 8 }) {
          Text('This account cannot view these stats').fontSize(12).fontColor('#6C7480')
          Button('Retry').fontSize(12).onClick(() => {
            this.dispatch('retry', {});
          })
        }.width('100%').alignItems(HorizontalAlign.Start)
      } else if (snapshot.locationRows.length === 0) {
        Text('Loading locations').fontSize(12).fontColor('#8C949C')
      } else {
        ForEach(snapshot.locationRows, (row: NewStatsLocationRowView) => {
          Row() {
            Text(row.label).fontSize(12).layoutWeight(1)
          }.width('100%')
        }, (row: NewStatsLocationRowView) => row.label)
      }
    }.width('100%').padding(12).backgroundColor('#FFFFFF').borderRadius(8)
  }

  build() {
    Stack() {
      if (this.ready) {
        Refresh({ refreshing: this.snapshot().showsRefreshing }) {
          Scroll() {
            Column({ space: 12 }) {
              this.periodHeader(this.snapshot())
              this.metricSelector(this.snapshot())
              this.chart(this.snapshot())
              this.summaryRow(this.snapshot())
              this.locationCard(this.snapshot())
            }.width('100%').padding({ left: 12, right: 12, bottom: 24 })
          }.width('100%').height('100%')
        }
        .onRefreshing(() => {
          this.dispatch('pullToRefresh', {});
        })
        .width('100%').height('100%')
      } else {
        Column({ space: 12 }) {
          LoadingProgress().width(32).height(32)
          Text('Loading New Stats').fontSize(14).fontColor('#6C7480')
        }.width('100%').height('100%').justifyContent(FlexAlign.Center)
      }
    }.width('100%').height('100%').backgroundColor('#F6F7F8')
  }
}

