      }

      if (snapshot.showsCached) {
        Text('Showing saved results while they are checked for updates')
          .fontSize(11).fontColor('#8C949C').padding({ left: 12, right: 12, top: 6 })
      }

      if (snapshot.canDrillDown) {
        Button('Go to ' + snapshot.selectedBucketLabel)
          .fontSize(12)
          .margin({ left: 12, top: 6, bottom: 6 })
          .onClick(() => {
            this.dispatch('drillIntoSelectedBucket', {});
          })
      }
    }.width('100%')
  }

  @Builder
  private summaryRow(snapshot: NewStatsScreenSnapshot) {
    Row({ space: 8 }) {
      ForEach(snapshot.summaryRow, (cell: NewStatsSummaryCellView) => {
        Column({ space: 2 }) {
          Text(cell.value.toString()).fontSize(15).fontWeight(FontWeight.Bold)
          Text(cell.metric).fontSize(11).fontColor('#6C7480')
        }.layoutWeight(1).alignItems(HorizontalAlign.Center)
      }, (cell: NewStatsSummaryCellView) => cell.metric)
    }.width('100%').padding(12).backgroundColor('#F6F7F8').borderRadius(8)
  }

  @Builder
  private locationCard(snapshot: NewStatsScreenSnapshot) {
    Column({ space: 8 }) {
      Row({ space: 8 }) {
        Text('Countries').fontSize(13).fontColor('#1D2329')
          .onClick(() => {
            const event: Record<string, Object> = {};
            event['locationType'] = 'countries';
            this.dispatch('selectLocationType', event);
          })
        Text('Regions').fontSize(13).fontColor('#1D2329')
          .onClick(() => {
            const event: Record<string, Object> = {};
            event['locationType'] = 'regions';
            this.dispatch('selectLocationType', event);
          })
        Blank()
      }.width('100%')

      if (snapshot.showsPlanGate) {
        Column({ space: 8 }) {
          Text('Region data needs a plan that includes it').fontSize(12).fontColor('#6C7480')
          Button(snapshot.planActionLabel).fontSize(12).onClick(() => {
            this.dispatch('openPlanAction', {});
          })
        }.width('100%').alignItems(HorizontalAlign.Start)
      } else if (snapshot.showsAuthError) {
        Column({ space: 8 }) {
          Text('This account cannot view these stats').fontSize(12).fontColor('#6C7480')
          Button('Retry').fontSize(12).onClick(() => {
            this.dispatch('retry', {});
          })
        }.width('100%').alignItems(HorizontalAlign.Start)
      } else if (snapshot.locationRows.length === 0) {
        Text('Loading locations').fontSize(12).fontColor('#8C949C')
      } else {
        ForEach(snapshot.locationRows, (row: NewStatsLocationRowView) => {
          Row() {
            Text(row.label).fontSize(12).layoutWeight(1)
          }.width('100%')
        }, (row: NewStatsLocationRowView) => row.label)
      }
    }.width('100%').padding(12).backgroundColor('#FFFFFF').borderRadius(8)
  }

  build() {
    Stack() {
      if (this.ready) {
        Refresh({ refreshing: this.snapshot().showsRefreshing }) {
          Scroll() {
            Column({ space: 12 }) {
              this.periodHeader(this.snapshot())
              this.metricSelector(this.snapshot())
              this.chart(this.snapshot())
              this.summaryRow(this.snapshot())
              this.locationCard(this.snapshot())
            }.width('100%').padding({ left: 12, right: 12, bottom: 24 })
          }.width('100%').height('100%')
        }
        .onRefreshing(() => {
          this.dispatch('pullToRefresh', {});
        })
        .width('100%').height('100%')
      } else {
        Column({ space: 12 }) {
          LoadingProgress().width(32).height(32)
          Text('Loading New Stats').fontSize(14).fontColor('#6C7480')
        }.width('100%').height('100%').justifyContent(FlexAlign.Center)
      }
    }.width('100%').height('100%').backgroundColor('#F6F7F8')
  }
}","path":"/Users/z1an/research/.ltb-wordpress-agent/wordpress_03_04_minimax_m3_20261023/04_new_stats/arkts/entry/src/main/ets/pages/Index.ets"}

