input.newString:
export function cloneRecord(source: Record<string, Object>): Record<string, Object> {
  return JSON.parse(JSON.stringify(source)) as Record<string, Object>;
}

/**
 * Publishes the screen state, rendering an absent bucket selection as an
 * explicit null so consumers can tell "nothing selected" apart from a
 * selection object with missing fields.
 */
function publishedState(source: Record<string, Object>): Record<string, Object> {
  const copy: Record<string, Object> = cloneRecord(source);
  const bar: Record<string, Object> = newStatsReadRecord(copy, 'selectedBar');
  copy['selectedBar'] = Object.keys(bar).length > 0 ? bar : absentValue();
  return copy;
}

/**
 * The state container cannot hold a null, so "no selection" is carried
 * internally as an empty record and represented on the way out by this marker,
 * which serialises to null.
 */
function absentValue(): Object {
  return new NewStatsAbsentValue();
}

class NewStatsAbsentValue {
  toJSON(): Object | undefined {
    return undefined;
  }
}

