private failed(channel: string, generation: number, outcome: string, errorCode: string): NewStatsRemoteResponse {
    return {
      channel: channel,
      outcome: outcome,
      httpStatus: 0,
      generation: generation,
      payload: emptyRecord(),
      errorCode: errorCode
    };
  }

  /**
   * A scripted outcome other than success is a failure. Anything that is not a
   * clean success must reach the store as a failure, otherwise a failed request
   * would be applied to the screen as though it had produced data.
   */
  private transportFailure(channel: string, request: NewStatsRemoteRequest, scripted: string): NewStatsRemoteResponse | undefined {
    if (scripted.length === 0 || scripted === NEW_STATS_OUTCOME_SUCCESS) {
      return undefined;
    }
    if (scripted === NEW_STATS_OUTCOME_NETWORK_ERROR) {
      return this.failed(channel, request.generation, NEW_STATS_OUTCOME_NETWORK_ERROR, 'offline');
    }
    if (scripted === NEW_STATS_OUTCOME_HTTP_ERROR) {
      return this.failed(channel, request.generation, NEW_STATS_OUTCOME_HTTP_ERROR, 'server_error');
    }
    return this.failed(channel, request.generation, scripted, 'unknown_error');
  }

